&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Must be a U.S. Citizen and&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;able to obtain and&amp;nbsp;maintain&amp;nbsp;a U.S. Top Secret security clearance&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
