&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;RF/microwave design in the Ku, Ka, V and E-band frequency range &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:20,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
